('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Social Engineering fördert Identitätsdiebstahl im Anwendersupport. b) Identitätsdiebstahl ist immer technisch vermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Social Engineering ja, nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

